function phosphorSvg(iconName) {
    var path = phosphorPaths[String(iconName || "")]
    if (!path)
        return ""
    var source = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256'"
            + " fill='black'><path d='" + path + "'/></svg>"
    return "data:image/svg+xml;utf8," + encodeURIComponent(source)
}

