function source(name) {
    var heroName = heroSemanticIcons[String(name || "")]
    if (heroName)
        return heroiconSvg(heroName)
    var iconName = semanticIcons[String(name || "")]
    return phosphorSvg(iconName)
}

function legacy(name) {
    var raw = String(name || "")
    var mapped = legacyCatalog[raw]
    if (!mapped)
        return "qrc:/InGe/Mobile/icons/" + raw
    if (String(mapped).indexOf("qrc:/") === 0)
        return mapped
    return source(mapped)
}

function has(name) {
    return source(name).length > 0
}

function category(name) {
    var prefix = String(name || "").split(".")[0]
    if (prefix === "nav")
        return "navigation"
    if (prefix === "action")
        return "actions"
    if (prefix === "documents" || prefix === "files")
        return "files"
    if (prefix === "module" || prefix === "calicatas"
            || prefix === "geotechnical")
        return "geotechnical"
    if (prefix === "map")
        return "map"
    if (prefix === "status")
        return "status"
    return "system"
}

function sourceForState(name, state) {
    var semanticState = String(state || "idle").toLowerCase()
    if (semanticState === "loading" && has("status.loading"))
        return source("status.loading")
    if (semanticState === "success" && has("status.success"))
        return source("status.success")
    if (semanticState === "warning" && has("status.warning"))
        return source("status.warning")
    if (semanticState === "error" && has("status.error"))
        return source("status.error")
    return source(name)
}
